USE launchkit;
ALTER TABLE sites MODIFY COLUMN color VARCHAR(7) NOT NULL DEFAULT '#d84937';
UPDATE sites SET color=CASE color WHEN 'violet' THEN '#69519a' WHEN 'green' THEN '#40715a' ELSE '#d84937' END WHERE color NOT REGEXP '^#[[:xdigit:]]{6}$';
ALTER TABLE sites ADD COLUMN secondary_color VARCHAR(7) NOT NULL DEFAULT '#fff2e6', ADD COLUMN text_color VARCHAR(7) NOT NULL DEFAULT '#252021', ADD COLUMN logo_path VARCHAR(220) NOT NULL DEFAULT '', ADD COLUMN business_type VARCHAR(25) NOT NULL DEFAULT 'other';
